principalClaims.statementTeX:
Put $q_{xy}=\epsilon_x\epsilon_y(v_x\cdot v_y)$ and
$f(q)=q^2+2q-3$. Then
\begin{equation}\label{stability:defect}
 A\delta=2\sum_xw_xh_x^2+
 \sum_{x\ne y}w_xw_y f(q_{xy}).
\end{equation}
Both terms are nonnegative. In particular $\delta\ge0$, and the
ordered mass of off-diagonal pairs with $q_{xy}\notin\{-3,1\}$ is
at most $A\delta/32$. Furthermore
\begin{equation}\label{stability:disp}
 \sum_xw_x|w_x-1/N|\le \sqrt{2\delta/A}+\delta.
\end{equation}

\label{thm:attainment-small-traps}
The following measures are nonglobal strict local maxima of $C$:
\begin{enumerate}
\item On four bits, writing $k$ for the number of negative coordinates,
assign mass $1/6$ at $k=0$, mass $1/12$ to every point with $k=2$ or
$k=3$, and mass zero otherwise.
\item On five bits, assign mass $1/6$ at $k=0$, mass $1/12$ to each
of the ten points with $k=3$, and zero otherwise.
\end{enumerate}
Both have $C=7/72$, whereas feasible measures with $C=1/8$ exist.

\label{prop:compression-complete-clique}
Every orthogonal $h$-subset of the augmented trap support extends to an
order-$2h$ Hadamard matrix with exactly $h$ trap rows.

The law
\[
 Q(x)=\frac{P(x)+(B-f(x))/M}{1+B}
\]
is nonnegative, normalized, unbiased and pairwise independent. Its
total variation distance from $P$ is at most $B/(1+B)$, and
\begin{equation}\label{collision}
 C(Q)=\frac1M+
 \frac{C(P)-(1+\sum_{1\le|S|\le2}m_S^2)/M}{(1+B)^2}
 \ \ge\ \frac{C(P)}{(1+B)^2}.
\end{equation}

\label{thm:rank-asymptotic}
There is an infinite sequence of classical known Hadamard orders $N$
and laws $P_N$ on $N-4$ bits such that
\begin{enumerate}
\item $C(P_N)=1/N$ and every first and second moment error tends to zero;
\item $P_N$ is at total-variation distance tending to zero from an
exactly unbiased pairwise-independent law;
\item its distance from every exact law on at most $N$ atoms tends to one.
\end{enumerate}
The exactly feasible laws in item two also have
$N C(U_N)\longrightarrow1$. Thus even vanishing moment error and
asymptotically optimal \emph{relative} collision do not give a
dimension-free total-variation rounding theorem to extremizers.

\label{ext:thm:entropy}
For every fixed $\eta>0$, all sufficiently large $m$ satisfy
\begin{equation}\label{ext:eq:entropy}
\log\ell_m(S)\le(r-1)m\log m+rm\log\log m+(\beta+\eta)m.
\end{equation}
In particular the normalized second-order remainder has limsup at most
$\beta$.
